import { useState, type FormEvent } from 'react'
import { AI_TOPICS, STATIC_TOPICS, type Topic } from '.'

/** Picks a learning topic: hand-written ones open instantly, the rest are generated by the AI. */
export function TopicsPanel({
  onPick,
  onCustom,
  onClose,
}: {
  onPick: (topic: Topic) => void
  onCustom: (title: string) => void
  onClose: () => void
}) {
  const [query, setQuery] = useState('')
  const matches = (topic: Topic) => `${topic.title} ${topic.blurb}`.toLowerCase().includes(query.trim().toLowerCase())

  function submitCustom(e: FormEvent) {
    e.preventDefault()
    if (query.trim()) onCustom(query.trim())
  }

  const item = (topic: Topic) => (
    <li key={topic.id}>
      <button type="button" className="topic" onClick={() => onPick(topic)}>
        <span className="topic-title">
          {topic.kind === 'ai' ? topic.title.replace(/^an? /, '').replace(/^./, (c) => c.toUpperCase()) : topic.title}
          <span className={`topic-badge is-${topic.kind}`}>{topic.kind === 'static' ? 'Instant' : 'AI'}</span>
        </span>
        <span className="topic-blurb">{topic.blurb}</span>
      </button>
    </li>
  )

  const ready = STATIC_TOPICS.filter(matches)
  const generated = AI_TOPICS.filter(matches)

  return (
    <aside className="explain topics" aria-label="Learning topics">
      <header className="explain-header">
        <h2>Learn a topic</h2>
        <button type="button" className="assistant-icon-btn" onClick={onClose} aria-label="Close topics">
          ×
        </button>
      </header>
      <form className="topics-search" onSubmit={submitCustom}>
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search, or type any topic…"
          aria-label="Search topics"
          autoFocus
        />
      </form>
      <div className="explain-scroll">
        {ready.length > 0 && (
          <>
            <h3>Ready to learn</h3>
            <p className="topics-note">Hand-written diagram, database and explanation. Opens instantly.</p>
            <ul className="topic-list">{ready.map(item)}</ul>
          </>
        )}
        {generated.length > 0 && (
          <>
            <h3>Generated by AI</h3>
            <p className="topics-note">Designed on demand by the assistant; slower, and different each time.</p>
            <ul className="topic-list">{generated.map(item)}</ul>
          </>
        )}
        {query.trim() && (
          <button type="button" className="assistant-chip" onClick={() => onCustom(query.trim())}>
            Design “{query.trim()}” with AI
          </button>
        )}
      </div>
    </aside>
  )
}
